args.query:
// Variante: fases da França que CONTÊM finalização (não necessariamente a última ação) e Mbappé tocou na bola
MATCH (f:FaseDePosse {match_id: 3869685})
WHERE EXISTS {
  MATCH (j:Jogador)-[r:REALIZOU]->(:Partida)
  WHERE r.match_id = 3869685 AND r.fase_posse_id = f.fase_id AND r.acao IN ['finalizacao','penalti']
}
AND EXISTS {
  MATCH (mb:Jogador)-[:PARTICIPOU_DE]->(f) WHERE mb.nome CONTAINS 'Mbapp'
}
MATCH (o:Jogador)-[po:PARTICIPOU_DE]->(f)
WHERE po.match_id = 3869685 AND NOT o.nome CONTAINS 'Mbapp'
RETURN o.nome AS companheiro, count(DISTINCT f.fase_id) AS jogadas_junto, sum(po.numero_de_toques) AS toques_nessas_jogadas
ORDER BY jogadas_junto DESC, toques_nessas_jogadas DESC
LIMIT 10
